"""v4 l4copy XAI + ablations, fold 0 (no submission). Built by scripts/build_kaggle_xai_kernel.py; the embedded files are
the repo's kaggle/submission_kernels/v4_l4copy_diag_fold0/run.py and scripts/l4copy_xai.py."""
import base64
import json
import os
import sys
import time
from multiprocessing import Pool
from pathlib import Path

EMB = {
"l4copy_diag_core.py": "",
"l4copy_xai.py": ""
}
os.environ.update({"XAI_NF": "1", "XAI_LITE": "1", "XAI_NOCASES": "1", "XAI_QPRIOR": "{\"quota\":[[4,0,0,0,0],[1,0,3,0,0],[3,0,1,0,0],[4,0,0,0,0],[3,1,0,0,0],[3,1,0,0,0],[3,1,0,0,0],[1,0,0,0,3],[2,0,2,0,0],[2,0,2,0,0]],\"median\":[[[223,194],[220,199],[217,206],[201,200],[186,217]],[[221,192],[214,189],[210,204],[200,200],[176,216]],[[230,208],[231,213],[220,197],[222,141],[218,216]],[[225,198],[223,202],[208,211],[192,192],[192,192]],[[226,195],[232,201],[226,188],[227,211],[190,206]],[[222,196],[221,197],[212,182],[196,218],[209,208]],[[214,187],[217,191],[228,202],[203,179],[200,205]],[[227,209],[224,204],[208,191],[172,140],[232,203]],[[226,186],[226,184],[214,181],[220,189],[176,192]],[[226,194],[226,200],[215,196],[224,202],[196,198]]],\"mix\":[[0.8383,0.0569,0.0732,0.0039,0.0277],[0.1358,0.0012,0.8556,0.0069,0.0006],[0.8408,0.0646,0.0935,0.0008,0.0003],[0.889,0.1105,0.0006,0.0,0.0],[0.6318,0.2894,0.0674,0.0097,0.0017],[0.7401,0.2529,0.0007,0.0002,0.0061],[0.7174,0.2584,0.0004,0.0003,0.0236],[0.1218,0.0121,0.0165,0.0011,0.8485],[0.5172,0.01,0.4183,0.0043,0.0501],[0.4608,0.0125,0.4668,0.0088,0.0511]],\"n_studies\":3524,\"slots\":[\"SagF\",\"SagNF\",\"CorF\",\"CorNF\",\"Ax\"],\"findings\":[\"ACL\",\"MCL\",\"MedialMeniscus\",\"LateralMeniscus\",\"MedialOA\",\"LateralOA\",\"PFOA\",\"Baker's\",\"Contusion\",\"Fracture\"]}"})
W = Path("/kaggle/working"); CODE = W / "code"; CODE.mkdir(exist_ok=True)
for name, b in EMB.items():
    (CODE / name).write_bytes(base64.b64decode(b))
sys.path.insert(0, str(CODE))


def find(slug):
    return next(p for p in (Path("/kaggle/input/datasets/tumis001") / slug, Path("/kaggle/input") / slug) if p.exists())


EXTRA = find("rsna-v4-xai-extra")
os.environ["XAI_CASES"] = str(EXTRA / "xai_cases.json")
import l4copy_diag_core as run  # noqa: E402
os.environ.setdefault("XAI_MODELS", ",".join([f"s2026={run.ART / run.sub.WEIGHTS['file']}",
                                              f"s2027={EXTRA / 'l4copy_s2027_swa21_25.pt'}",
                                              f"r1self={EXTRA / 'r1_self_s2026_swa21_25.pt'}"]))
import l4copy_xai as xai  # noqa: E402
import torch  # noqa: E402

sub = run.sub


def main():
    t0 = time.monotonic()
    sub.ensure_timm()
    data = sub.competition_dir()
    ids = json.loads((find("rsna-d96-fold0-ids") / "fold0_ids.json").read_text()); assert len(ids) == 825, len(ids)
    if os.environ.get("XAI_N"):
        ids = ids[:int(os.environ["XAI_N"])]
    tabm = run.ms1_table(); assert all(s in tabm for s in ids)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    models = xai.load_models(device)
    case_of = xai.case_index(ids)
    by_study = {}
    for row in sub.read_csv(data / "train_series.csv"):
        by_study.setdefault(row["StudyInstanceUID"], []).append(row)
    errors = [0]

    def items(it):
        for sid, vol, mask, err in it:
            errors[0] += err
            yield sid, vol, mask

    with Pool(4) as procs:
        it = procs.imap(sub.build_study, [(s, by_study.get(s, []), data / "train_series") for s in ids])
        R, panels, checks, done = xai.loop(items(it), len(ids), models, tabm, case_of, device, t0)
    xai.save(W, done, models, R, panels, checks, {"source": "kaggle DICOM (sub.build_study)", "decode_errors": errors[0],
             "device": torch.cuda.get_device_name() if device.type == "cuda" else "cpu",
             "seconds": round(time.monotonic() - t0, 1)})


if __name__ == "__main__":
    main()
